def split_words(txt):
    # Remove trailing comma if any
    txt = txt.rstrip(',')

    # Check for whitespace
    if ' ' in txt:
        words = txt.split()
    elif ',' in txt:
        words = txt.split(',')
    else:
        # Count odd letters with odd order in the alphabet
        odd_letters = 0
        for letter in txt:
            if ord(letter) % 2 != 0:
                odd_letters += 1
        return odd_letters
    return words
