def bf(planet1, planet2):
    # Check if the inputs are valid planet names
    if not (isinstance(planet1, str) and isinstance(planet2, str)):
        return ()

    # Create a list of planet names sorted by proximity to the sun
    planets = sorted([planet for planet in ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]])

    # Find planets between the given planets
    if planet1 in planets and planet2 in planets:
        return tuple(planets[(planets.index(planet1) + 1):(planets.index(planet2) - 1)])
    else:
        return ()

# Example usage
